draw:
var GM = 3.986e14, Re = 6.37e6;
var r = p.rr * Re;
var v = Math.sqrt(GM / r);
var T = 2 * Math.PI * r / v;
var ve = Math.SQRT2 * v;
var gh = GM / (r * r);

var cx = W * 0.40, cy = H * 0.52;
var span = Math.min(W * 0.50, H * 0.46);
var s = span / 8.6;           // pixels per Earth radius
var Rp = s;                   // planet radius in px
var Ro = p.rr * s;            // orbit radius in px

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// orbit circle
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([4, 5]);
ctx.beginPath();
ctx.arc(cx, cy, Ro, 0, Math.PI * 2);
ctx.stroke();
ctx.setLineDash([]);

// planet
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(cx, cy, Rp, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.paper;
ctx.textAlign = "center";
ctx.fillText("Earth", cx, cy + 4);

// satellite: visual period keeps Kepler scaling
var visT = 2.6 * Math.pow(p.rr, 1.5);
var ang = 2 * Math.PI * (t % visT) / visT;
var sxp = cx + Ro * Math.cos(ang);
var syp = cy - Ro * Math.sin(ang);

// radius line
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(sxp, syp);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("r", (cx + sxp) / 2 + 5, (cy + syp) / 2 - 5);

// velocity arrow (tangent) and gravity arrow (inward)
var tx = -Math.sin(ang), ty = -Math.cos(ang);
var vlen = 16 + 26 * (v / 7900);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(sxp, syp);
ctx.lineTo(sxp + tx * vlen, syp + ty * vlen);
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("v", sxp + tx * vlen + 4, syp + ty * vlen + 4);

var gx = (cx - sxp), gy = (cy - syp);
var gm = Math.sqrt(gx * gx + gy * gy);
var glen = 10 + 34 * (gh / 9.81);
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(sxp, syp);
ctx.lineTo(sxp + gx / gm * glen, syp + gy / gm * glen);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("g", sxp + gx / gm * glen - 12, syp + gy / gm * glen - 4);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(sxp, syp, 4.5, 0, Math.PI * 2);
ctx.fill();

// side panel of numbers
var px0 = W * 0.74;
ctx.textAlign = "left";
ctx.fillStyle = C.ink;
ctx.fillText("r = " + (p.rr).toFixed(2) + " R_E", px0, H * 0.30);
ctx.fillText("v = " + v.toFixed(0) + " m/s", px0, H * 0.30 + 18);
ctx.fillText("T = " + (T / 3600).toFixed(2) + " h", px0, H * 0.30 + 36);
ctx.fillStyle = C.figure;
ctx.fillText("g = " + gh.toFixed(2) + " m/s^2", px0, H * 0.30 + 54);

out.note = "r = " + (r / 1e6).toFixed(2) + "e6 m, v = " + v.toFixed(0) +
  " m/s, T = " + T.toFixed(0) + " s (" + (T / 3600).toFixed(2) +
  " h), escape speed here = " + ve.toFixed(0) + " m/s";

var k = p.ratio;                 // M1 / M2
var d = 1.0;
var x0 = d / (1 + Math.sqrt(1 / k));   // null point, fraction of d from M1

var pad = W * 0.12;
var y0 = H * 0.58;
var X = function (u) { return pad + u * (W - 2 * pad); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// axis
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(X(0), y0);
ctx.lineTo(X(1), y0);
ctx.stroke();

// bodies, radius by cube root of mass
var r1 = 9 * Math.pow(k / (k + 1), 1 / 3) * 1.25;
var r2 = 9 * Math.pow(1 / (k + 1), 1 / 3) * 1.25;
if (r1 < 5) { r1 = 5; }
if (r2 < 4) { r2 = 4; }
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(0), y0, r1, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(1), y0, r2, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("M1 (heavy)", X(0), y0 + r1 + 16);
ctx.fillText("M2", X(1), y0 + r2 + 16);
ctx.fillText("separation d", X(0.5), y0 + 38);

// field arrows above the line
var i, u, f, mag, dir, len;
for (i = 1; i <= 17; i++) {
  u = i / 18;
  if (Math.abs(u - x0) < 0.012) { continue; }
  f = -k / (u * u) + 1 / ((1 - u) * (1 - u));   // positive means toward M1
  dir = f > 0 ? -1 : 1;                          // arrow points toward pull
  mag = Math.abs(f);
  len = 6 + 26 * (mag / (mag + 6));
  ctx.strokeStyle = dir < 0 ? C.figure : C.accent;
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(X(u), y0 - 26);
  ctx.lineTo(X(u) + dir * len, y0 - 26);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(X(u) + dir * len, y0 - 26);
  ctx.lineTo(X(u) + dir * (len - 5), y0 - 31);
  ctx.lineTo(X(u) + dir * (len - 5), y0 - 21);
  ctx.closePath();
  ctx.fillStyle = dir < 0 ? C.figure : C.accent;
  ctx.fill();
}

// null marker
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.5;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(X(x0), y0 - 48);
ctx.lineTo(X(x0), y0 + 10);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("net field = 0", X(x0), y0 - 56);
ctx.fillText("x = " + x0.toFixed(3) + " d", X(x0), H * 0.97);

ctx.textAlign = "left";
ctx.fillStyle = C.faint;
ctx.fillText("arrows show which way a stone would accelerate", pad, H * 0.12);

out.note = "M1/M2 = " + k.toFixed(0) + "  ->  null point at x = " + x0.toFixed(4) +
  " d from M1 (for Earth and Moon, ratio 81, that is 3.456e8 m of 3.84e8 m)";

var GM = 3.986e14, Re = 6.37e6;
var r0 = p.r0 * Re;
var vc = Math.sqrt(GM / r0);
var v = p.k * vc;
var E = 0.5 * v * v - GM / r0;          // per kilogram
var rmaxPhys = E < 0 ? -GM / E : Infinity;

var padL = W * 0.13, padR = W * 0.05, padT = H * 0.16, padB = H * 0.20;
var rMin = 1, rMax = 12;                 // in Earth radii
var Umin = -GM / (rMin * Re);            // most negative
var yTop = -Umin * 0.32;                 // a little headroom above zero
var X = function (rr) { return padL + (rr - rMin) / (rMax - rMin) * (W - padL - padR); };
var Y = function (u) { return padT + (yTop - u) / (yTop - Umin) * (H - padT - padB); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(padL, padT);
ctx.lineTo(padL, H - padB);
ctx.lineTo(W - padR, H - padB);
ctx.stroke();

// U = 0 line
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath();
ctx.moveTo(padL, Y(0));
ctx.lineTo(W - padR, Y(0));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("U = 0 at infinity", padL + 6, Y(0) - 5);

// U(r) curve
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
var i, rr, u;
for (i = 0; i <= 200; i++) {
  rr = rMin + (rMax - rMin) * i / 200;
  u = -GM / (rr * Re);
  if (i === 0) { ctx.moveTo(X(rr), Y(u)); } else { ctx.lineTo(X(rr), Y(u)); }
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("U(r) = -GMm/r", X(7.2), Y(-GM / (7.2 * Re)) + 18);

// total energy line
var Eclamped = E > yTop ? yTop : (E < Umin ? Umin : E);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.8;
ctx.beginPath();
ctx.moveTo(padL, Y(Eclamped));
ctx.lineTo(W - padR, Y(Eclamped));
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.textAlign = "right";
ctx.fillText("total E", W - padR - 4, Y(Eclamped) - 6);

// launch point marker
ctx.strokeStyle = C.ink;
ctx.setLineDash([3, 3]);
ctx.beginPath();
ctx.moveTo(X(p.r0), Y(-GM / r0));
ctx.lineTo(X(p.r0), Y(Eclamped));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("K here", X(p.r0), (Y(-GM / r0) + Y(Eclamped)) / 2 + 4);
ctx.fillText("launch r0", X(p.r0), H - padB + 16);

// turning point
if (E < 0 && rmaxPhys / Re <= rMax) {
  var rt = rmaxPhys / Re;
  ctx.fillStyle = C.accent;
  ctx.beginPath();
  ctx.arc(X(rt), Y(E), 4.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillText("turns back", X(rt), Y(E) - 10);
}

// axis labels
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("distance from centre (Earth radii)", (padL + W - padR) / 2, H - 6);
ctx.textAlign = "left";
ctx.fillText("energy per kg", padL - 6, padT - 6);

if (E >= 0) {
  out.note = "launch speed " + v.toFixed(0) + " m/s at r0 = " + p.r0.toFixed(1) +
    " R_E: E >= 0, the body escapes (escape speed here is " +
    (Math.SQRT2 * vc).toFixed(0) + " m/s)";
} else {
  out.note = "launch speed " + v.toFixed(0) + " m/s at r0 = " + p.r0.toFixed(1) +
    " R_E: bound, it rises to " + (rmaxPhys / Re).toFixed(2) +
    " R_E and falls back (escape would need " + (Math.SQRT2 * vc).toFixed(0) + " m/s)";
}
